import{_ as a,o,c as t,a0 as p}from"./chunks/framework.jwovEGr5.js";const l="/assets/%E6%95%B0%E6%8D%AE%E7%BA%BF.LJcf51TA.webp",i="/assets/%E6%96%87%E4%BB%B6%E4%BC%A0%E8%BE%931.DOUYl5QP.webp",s="/assets/%E6%96%87%E4%BB%B6%E4%BC%A0%E8%BE%932.DY1miO1h.webp",c="/assets/%E6%96%87%E4%BB%B6%E4%BC%A0%E8%BE%933.Dv1k7JEH.webp",r="/assets/%E6%96%87%E4%BB%B6%E4%BC%A0%E8%BE%934.Bv1jcvrH.webp",d="data:image/webp;base64,",n="/assets/%E6%96%87%E4%BB%B6%E4%BC%A0%E8%BE%936.B93ThcM-.webp",h="/assets/%E6%96%87%E4%BB%B6%E4%BC%A0%E8%BE%937.D5JTf990.webp",m="/assets/%E5%9B%BE%E7%89%87%E6%A0%BC%E5%BC%8F1.B1bYYXvm.webp",B="/assets/%E5%9B%BE%E7%89%87%E6%A0%BC%E5%BC%8F2.CElU8-JG.webp",C=JSON.parse('{"title":"文件（图片）传输","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"电脑知识/文件传输.md","filePath":"电脑知识/文件传输.md"}'),u={name:"电脑知识/文件传输.md"};function b(A,e,E,q,f,P){return o(),t("div",null,[...e[0]||(e[0]=[p('<h1 id="文件-图片-传输" tabindex="-1">文件（图片）传输 <a class="header-anchor" href="#文件-图片-传输" aria-label="Permalink to &quot;文件（图片）传输&quot;">​</a></h1><h2 id="手机与电脑互传" tabindex="-1">手机与电脑互传 <a class="header-anchor" href="#手机与电脑互传" aria-label="Permalink to &quot;手机与电脑互传&quot;">​</a></h2><h3 id="_1、微信-qq文件传输助手" tabindex="-1">1、微信/QQ文件传输助手 <a class="header-anchor" href="#_1、微信-qq文件传输助手" aria-label="Permalink to &quot;1、微信/QQ文件传输助手&quot;">​</a></h3><p>适用于小文件</p><p>电脑登录微信/QQ，找到文件传输助手，或者发送给自己，直接拖拽文件即可发送</p><h3 id="_2、通过数据线传输" tabindex="-1">2、通过数据线传输 <a class="header-anchor" href="#_2、通过数据线传输" aria-label="Permalink to &quot;2、通过数据线传输&quot;">​</a></h3><ol><li>准备数据线</li></ol><p>一般情况下你的充电线就是一根数据线，但确实有的只有充电功能，没有数据线路。优先使用手机原装数据线。</p><p><img src="'+l+`" alt="数据线" width="200px"></p><ol start="2"><li><p>数据线一头插手机Type-C口，另一头直接插电脑主板USB口（台式机优先机箱后面接口）</p></li><li><p>USB连接选项</p></li></ol><p>一般情况下，打开手机就会直接在下方显示链接选项，且默认为<code>仅充电</code></p><p>你也可以从手机屏幕顶部往下拉开通知栏，找到通知：通过USB为设备充电，点击这条通知，打开USB连接选项</p><ol start="4"><li>点击<code>仅传输照片</code>选项，此时你的电脑可以访问手机相册；点击<code>仅传输文件</code>选项，此时你的电脑可以访问手机的文件</li></ol><blockquote><p>你的手机也仍在充电中（一边充电一边传输）</p></blockquote><ol start="5"><li>桌面打开电脑<code>此电脑</code>（Windows+e），找到你的手机（例如<code>荣耀畅玩</code>），里面会出现DCIM等文件夹，把需要的文件剪切到我们的电脑即可</li></ol><h5 id="只有充电选项" tabindex="-1">只有充电选项 <a class="header-anchor" href="#只有充电选项" aria-label="Permalink to &quot;只有充电选项&quot;">​</a></h5><p>一般来说大概率是因为使用了充电专用线，而非数据线，一定只有数据线才能传输文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单靠外观不能100%保证准确区分是否为数据线</span></span>
<span class="line"><span></span></span>
<span class="line"><span>推荐看线上的印刷文字标识，数据线会标注 USB2.0/USB3.0/Sync/DataTransfer（同步/数据传输）</span></span></code></pre></div><p>还有可能是接触不良，包括数据线接口接触不良和USB接口接触不良，此时可以更换电脑上另外一个USB接口尝试</p><h3 id="_3、云盘传输" tabindex="-1">3、云盘传输 <a class="header-anchor" href="#_3、云盘传输" aria-label="Permalink to &quot;3、云盘传输&quot;">​</a></h3><p>适合异地互传，但是速度受网速、会员限制，大文件上传下载耗流量，同时，敏感信息容易泄露</p><h2 id="电脑之间互传" tabindex="-1">电脑之间互传 <a class="header-anchor" href="#电脑之间互传" aria-label="Permalink to &quot;电脑之间互传&quot;">​</a></h2><h3 id="_1、共享文件-夹" tabindex="-1">1、共享文件（夹） <a class="header-anchor" href="#_1、共享文件-夹" aria-label="Permalink to &quot;1、共享文件（夹）&quot;">​</a></h3><p>首先确保两台电脑连接在同一局域网内（连接同一网络）</p><p>为了讲解方便，假设你需要将<code>A电脑</code>上的文件传输给<code>B电脑</code></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><code>A电脑</code>要设置好开机密码，没有开机密码大概率是不允许共享的</p></div><ol><li>对A电脑操作：右键你需要传输的文件（如果文件在桌面，可以在<code>此电脑</code>内右键<code>桌面</code>）</li><li>点击<code>授予访问权限</code>中的<code>特定用户...</code>（win11：右键 → 显示更多选项 → 授予访问权限），进入到下方页面</li></ol><p><img src="`+i+'" alt="文件传输1" width="500"></p><ol start="3"><li>此时，选择<code>Everyone</code>，添加，在下方更改权限：更改为<code>读取/写入</code>，然后点击最下方的<code>共享</code>，此步骤需要管理员权限</li></ol><p><img src="'+s+'" alt="文件传输2" width="500"></p><p><img src="'+c+'" alt="文件传输3" width="500"></p><p>成功共享如下：</p><p><img src="'+r+'" alt="文件传输4" width="500"></p><p>若是文件夹共享成功，点进共享文件夹后，左下方还会有<code>已共享</code>的小提示</p><p><img src="'+d+'" alt="文件传输5"></p><p><strong>上述步骤成功之后，可以继续进行下一步，对B电脑操作：找到A电脑的共享文件夹：</strong></p><p>方法一（有可能不行）：打开<code>B电脑</code>的此电脑，找到<code>网络</code>，计算机栏目下面会出现另一台电脑（Home是自己的电脑），点开另一台电脑，输入<code>A电脑</code>的用户和开机密码，即可查看共享文件夹</p><p>方法二：按下<code>windows键</code>+<code>R</code>（或者：在开始菜单搜索：命令提示符，进入），输入A电脑的IPv4，输入<code>A电脑</code>的用户和开机密码，即可进入共享文件夹</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>关于如何查看A电脑的用户、IPv4：</p><p>在A电脑中，按下<code>windows键</code>+<code>R</code>，输入<code>cmd</code>，回车进入命令行（或者：在开始菜单搜索：命令提示符，进入）</p><p>输入命令<code>whoami</code>，可以查看当前你的用户名是什么（其结构为：你的设备名称\\你的用户名）</p><p>输入命令<code>ipconfig</code>，找到当前的IPv4是什么（示例：192.168.1.100）</p></div><p><strong>文件传输完毕后，结束共享：</strong></p><ol><li>点击<code>授予访问权限</code>中的<code>删除访问</code></li></ol><p><img src="'+n+'" alt="文件传输6" width="500"></p><ol start="2"><li>点击<code>停止共享</code></li></ol><h5 id="只有高级共享的选项" tabindex="-1">只有高级共享的选项 <a class="header-anchor" href="#只有高级共享的选项" aria-label="Permalink to &quot;只有高级共享的选项&quot;">​</a></h5><ul><li>磁盘根目录（D:\\ 这种盘根）</li><li>系统文件夹、Program Files</li><li>OneDrive 同步文件夹、网络映射盘</li><li>压缩包内文件夹</li></ul><p>对A电脑上待传输的文件操作：授予访问权限 → 高级共享 → 高级共享（按钮），来到下方的页面</p><p><img src="'+h+'" alt="文件传输7" width="400"></p><p>点击<code>共享此文件</code>，在权限中允许读取（默认允许）和更改（需要手动允许），最后点击<code>应用</code></p><p><strong>结束共享:</strong></p><p>点击高级共享，取消勾选<code>共享此文件</code>，确定</p><h3 id="_2、云盘传输" tabindex="-1">2、云盘传输 <a class="header-anchor" href="#_2、云盘传输" aria-label="Permalink to &quot;2、云盘传输&quot;">​</a></h3><p>适合异地互传，但是速度受网速、会员限制，大文件上传下载耗流量，同时，敏感信息容易泄露</p><h2 id="小知识" tabindex="-1">小知识 <a class="header-anchor" href="#小知识" aria-label="Permalink to &quot;小知识&quot;">​</a></h2><h3 id="dcim-pictures" tabindex="-1">DCIM &amp; Pictures <a class="header-anchor" href="#dcim-pictures" aria-label="Permalink to &quot;DCIM &amp; Pictures&quot;">​</a></h3><p>DCIM就是Digital Camera Images（数字相机图像）</p><p>是你亲手用相机拍摄的原图/原视频</p><p>而Pictures是非相机拍摄的各类图片</p><p>例如截图、网上保存图片、软件下载、表情包、修图后的副本。</p><blockquote><p>当然凡事都是有特例的</p></blockquote><h3 id="一些文件介绍" tabindex="-1">一些文件介绍 <a class="header-anchor" href="#一些文件介绍" aria-label="Permalink to &quot;一些文件介绍&quot;">​</a></h3><p>如下图</p><p><img src="'+m+'" alt="图片格式1"></p><ol><li><strong>cache文件夹</strong></li></ol><p>cache是缓存文件夹，相机APP运行时自动生成，存放图片预览图、处理过程临时素材、缩略图缓存。</p><p>可以删除；删掉后图库加载图片会稍微慢一点，打开相机后系统会自动重建缓存。</p><ol start="2"><li><strong>.inside（0字节空文件）</strong></li></ol><p>这类0KB隐藏空文件，是相机应用生成的标记/锁文件。</p><p>作用：标记文件夹状态、防止进程冲突。文件里面没有任何数据。</p><ol start="3"><li><strong>IMG_xxxx.jpg.tmp文件</strong></li></ol><p>.tmp是Temporary临时文件</p><p>产生原因：</p><ol><li>拍照瞬间发生中断</li><li>手机拍照时突然锁屏/闪退</li><li>拍照过程存储空间不足</li><li>文件传输中断（手机连电脑拷贝照片中途断开）</li></ol><p>运行逻辑：</p><p>相机先写入临时文件.jpg.tmp，照片完整保存成功后，后缀自动去掉.tmp，变成正常jpg图片。</p><p>所以当保存失败时，就会遗留这个tmp文件。</p><h5 id="tmp两种情况区分" tabindex="-1">.tmp两种情况区分 <a class="header-anchor" href="#tmp两种情况区分" aria-label="Permalink to &quot;.tmp两种情况区分&quot;">​</a></h5><p>那个有大小的tmp文件（例如那个2.92MB的文件）</p><p>可以尝试【重命名】删掉末尾.tmp，变成IMG_xxxx.jpg，看看能不能打开图片，一般来说会有数据损坏。</p><p>0字节的.jpg.tmp文件,完全是空文件，没有任何图像数据，无法恢复。</p><p>更改后如下图</p><p><img src="'+B+'" alt="图片格式2"></p><p>像这种本身大小比较大的，里面的文件损毁较小，只是有点不清晰</p>',82)])])}const v=a(u,[["render",b]]);export{C as __pageData,v as default};
